adcs_vec3_t h_body = {0, 0, 0};
double req_power[4], mot_sum = 0.0, reg_sum = 0.0, net_req = 0.0;
double mot_scale = 1.0, reg_scale = 1.0, desired[4], limited[4];
double del_mot = 0.0, del_reg = 0.0, del_net = 0.0;
unint32 power_mask = 0U, slew_mask = 0U;
int invalid = 0;
int dir_limiting = 0;
int slew_limiting = 0;
int any_limiting = 0;

if ((wp_config.release_filtered_w < 0.0) ||
    (wp_config.release_filtered_w >= wp_config.trip_filtered_w) ||
    (wp_config.filter_alpha < 0.0) || (wp_config.filter_alpha > 1.0) ||
    (wp_config.motoring_limit_w <= 0.0) || (wp_config.regenerative_limit_w <= 0.0) ||
    (wp_config.max_torque_slew_nm_per_cycle <= 0.0) ||
    (wp_config.release_cycles < 1U) || (wp_config.release_cycles > 20U)) {
    invalid = 1;
}
if ((wp_input.wheels == NULL) || (wp_input.torque_nm == NULL) || (wp_input.wheel_count != 4U)) {
    invalid = 1;
}
for (i = 0; (i < 4U) && (!invalid); i++) {
    if ((!isfinite(wp_input.torque_nm[i])) ||
        (!isfinite(wp_input.wheels[i].speed_rad_s)) ||
        (!isfinite(wp_input.wheels[i].inertia_kg_m2)) ||
        (!adcs_is_finite_vec3(&wp_input.wheels[i].axis_body))) {
        invalid = 1;
    }
}

if (invalid) {
    wp_state.mode = WP_FAULT;
    wp_state.clean = 0U;
    wp_state.filtered_abs_power_w = 0.0;
    for (i = 0; i < 4U; i++) {
        wp_state.previous_torque_nm[i] = 0.0;
        wp_output.limited_torque_nm[i] = 0.0;
    }
    wp_output.mode = WP_FAULT;
    wp_output.clean = 0U;
    wp_output.power_limited_mask = 0U;
    wp_output.slew_limited_mask = 0U;
    wp_output.requested_net_power_w = 0.0;
    wp_output.delivered_net_power_w = 0.0;
    wp_output.requested_motoring_power_w = 0.0;
    wp_output.requested_regenerative_power_w = 0.0;
    wp_output.delivered_motoring_power_w = 0.0;
    wp_output.delivered_regenerative_power_w = 0.0;
    wp_output.filtered_abs_power_w = 0.0;
    wp_output.momentum_norm_nms = 0.0;
    wp_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wp_output.requested_body_torque_nm = (adcs_vec3_t){0, 0, 0};
    wp_output.delivered_body_torque_nm = (adcs_vec3_t){0, 0, 0};
    return;
}

if (!wp_input.enable) {
    wp_state.mode = WP_NORMAL;
    wp_state.clean = 0U;
    wp_state.filtered_abs_power_w = 0.0;
    for (i = 0; i < 4U; i++) {
        wp_state.previous_torque_nm[i] = 0.0;
    }
    wp_output.mode = WP_NORMAL;
    wp_output.clean = 0U;
    wp_output.power_limited_mask = 0U;
    wp_output.slew_limited_mask = 0U;
    wp_output.requested_net_power_w = 0.0;
    wp_output.delivered_net_power_w = 0.0;
    wp_output.requested_motoring_power_w = 0.0;
    wp_output.requested_regenerative_power_w = 0.0;
    wp_output.delivered_motoring_power_w = 0.0;
    wp_output.delivered_regenerative_power_w = 0.0;
    wp_output.filtered_abs_power_w = 0.0;
    for (i = 0; i < 4U; i++) {
        wp_output.limited_torque_nm[i] = 0.0;
    }
    wp_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wp_output.momentum_norm_nms = 0.0;
    wp_output.requested_body_torque_nm = (adcs_vec3_t){0, 0, 0};
    wp_output.delivered_body_torque_nm = (adcs_vec3_t){0, 0, 0};
    return;
}

for (i = 0; i < 4U; i++) {
    req_power[i] = wp_input.torque_nm[i] * wp_input.wheels[i].speed_rad_s;
    net_req += req_power[i];
    if (req_power[i] > 0.0) {
        mot_sum += req_power[i];
    } else if (req_power[i] < 0.0) {
        reg_sum += -req_power[i];
    }
}

if (mot_sum > wp_config.motoring_limit_w) {
    mot_scale = wp_config.motoring_limit_w / mot_sum;
    dir_limiting = 1;
}
if (reg_sum > wp_config.regenerative_limit_w) {
    reg_scale = wp_config.regenerative_limit_w / reg_sum;
    dir_limiting = 1;
}

for (i = 0; i < 4U; i++) {
    double p = req_power[i];
    if (p > 0.0) {
        desired[i] = wp_input.torque_nm[i] * mot_scale;
        if (mot_scale < 1.0) {
            power_mask |= (unint32)(1U << i);
        }
    } else if (p < 0.0) {
        desired[i] = wp_input.torque_nm[i] * reg_scale;
        if (reg_scale < 1.0) {
            power_mask |= (unint32)(1U << i);
        }
    } else {
        desired[i] = 0.0;
    }
}

for (i = 0; i < 4U; i++) {
    double delta = desired[i] - wp_state.previous_torque_nm[i];
    if (delta > wp_config.max_torque_slew_nm_per_cycle) {
        limited[i] = wp_state.previous_torque_nm[i] + wp_config.max_torque_slew_nm_per_cycle;
        slew_mask |= (unint32)(1U << i);
        slew_limiting = 1;
    } else if (delta < -wp_config.max_torque_slew_nm_per_cycle) {
        limited[i] = wp_state.previous_torque_nm[i] - wp_config.max_torque_slew_nm_per_cycle;
        slew_mask |= (unint32)(1U << i);
        slew_limiting = 1;
    } else {
        limited[i] = desired[i];
    }
}

for (i = 0; i < 4U; i++) {
    double p = limited[i] * wp_input.wheels[i].speed_rad_s;
    del_net += p;
    if (p > 0.0) {
        del_mot += p;
    } else if (p < 0.0) {
        del_reg += -p;
    }
    if (adcs_vec3_normalize(&wp_input.wheels[i].axis_body, ADCS_EPS_NORM, &axis_i) != ADCS_OK) {
        wp_state.mode = WP_FAULT;
        wp_output.mode = WP_FAULT;
        return;
    }
    term = adcs_vec3_scale(&axis_i, wp_input.torque_nm[i]);
    req_body_torque = adcs_vec3_add(&req_body_torque, &term);
    term = adcs_vec3_scale(&axis_i, limited[i]);
    del_body_torque = adcs_vec3_add(&del_body_torque, &term);
}

(void)adcs_wheel_momentum(wp_input.wheels, wp_input.wheel_count, &h_body);
wp_output.momentum_nms = h_body;
wp_output.momentum_norm_nms = adcs_vec3_norm(&h_body);
wp_output.requested_body_torque_nm = adcs_vec3_scale(&req_body_torque, -1.0);
wp_output.delivered_body_torque_nm = adcs_vec3_scale(&del_body_torque, -1.0);

wp_state.filtered_abs_power_w = wp_config.filter_alpha * fabs(net_req) +
                                (1.0 - wp_config.filter_alpha) * wp_state.filtered_abs_power_w;

any_limiting = dir_limiting || slew_limiting ||
               (wp_state.filtered_abs_power_w >= wp_config.trip_filtered_w);

if (any_limiting) {
    wp_state.mode = WP_LIMITED;
    wp_state.clean = 0U;
} else if (wp_state.filtered_abs_power_w <= wp_config.release_filtered_w) {
    if (wp_state.mode == WP_LIMITED || wp_state.mode == WP_RECOVERING) {
        if (wp_state.clean == 0U) {
            wp_state.clean = 1U;
        } else {
            wp_state.clean += 1U;
        }
        if (wp_state.clean >= wp_config.release_cycles) {
            wp_state.mode = WP_NORMAL;
            wp_state.clean = 0U;
        } else {
            wp_state.mode = WP_RECOVERING;
        }
    } else {
        wp_state.mode = WP_NORMAL;
        wp_state.clean = 0U;
    }
} else {
    if (wp_state.mode != WP_LIMITED && wp_state.mode != WP_RECOVERING) {
        wp_state.mode = WP_NORMAL;
    }
    wp_state.clean = 0U;
}

for (i = 0; i < 4U; i++) {
    wp_output.limited_torque_nm[i] = limited[i];
    wp_state.previous_torque_nm[i] = limited[i];
}
wp_output.mode = wp_state.mode;
wp_output.clean = wp_state.clean;
wp_output.power_limited_mask = power_mask;
wp_output.slew_limited_mask = slew_mask;
wp_output.requested_net_power_w = net_req;
wp_output.delivered_net_power_w = del_net;
wp_output.requested_motoring_power_w = mot_sum;
wp_output.requested_regenerative_power_w = reg_sum;
wp_output.delivered_motoring_power_w = del_mot;
wp_output.delivered_regenerative_power_w = del_reg;
wp_output.filtered_abs_power_w = wp_state.filtered_abs_power_w;

