    wp_output.delivered_body_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

for (i = 0; i < 4U; i++) {
    mech_power[i] = torque_nm[i] * wheels[i].speed_rad_s;
    if (mech_power[i] >= 0.0) {
        motoring_contrib[i] = mech_power[i];
        regen_contrib[i] = 0.0;
        req_motoring_w += mech_power[i];
    } else {
        motoring_contrib[i] = 0.0;
        regen_contrib[i] = -mech_power[i];
        req_regen_w += -mech_power[i];
    }
    req_net_w += mech_power[i];
}

if (req_motoring_w > wp_config.motoring_limit_w && req_motoring_w > 0.0) {
    scale_mot = wp_config.motoring_limit_w / req_motoring_w;
}
if (req_regen_w > wp_config.regenerative_limit_w && req_regen_w > 0.0) {
    scale_reg = wp_config.regenerative_limit_w / req_regen_w;
}

for (i = 0; i < 4U; i++) {
    double scaled_power = motoring_contrib[i] * scale_mot + regen_contrib[i] * scale_reg;
    double torque_dir = (mech_power[i] >= 0.0) ? scale_mot : scale_reg;
    double limited_torque = torque_nm[i] * torque_dir;
    double delta = limited_torque - wp_state.previous_torque_nm[i];
    double max_slew = wp_config.max_torque_slew_nm_per_cycle;
    double limit_slew;
    (void)scaled_power;
    if (delta > max_slew) {
        limit_slew = wp_state.previous_torque_nm[i] + max_slew;
        slew_mask |= (uint32_t)(1U << i);
        any_slew_limit = 1;
    } else if (delta < -max_slew) {
        limit_slew = wp_state.previous_torque_nm[i] - max_slew;
        slew_mask |= (uint32_t)(1U << i);
        any_slew_limit = 1;
    } else {
        limit_slew = limited_torque;
    }
    wp_output.limited_torque_nm[i] = limit_slew;
}

if (req_motoring_w > wp_config.motoring_limit_w && req_motoring_w > 0.0) {
    any_power_limit = 1;
    for (i = 0; i < 4U; i++)
        if (motoring_contrib[i] > 0.0)
            power_mask |= (uint32_t)(1U << i);
}
if (req_regen_w > wp_config.regenerative_limit_w && req_regen_w > 0.0) {
    any_power_limit = 1;
    for (i = 0; i < 4U; i++)
        if (regen_contrib[i] > 0.0)
            power_mask |= (uint32_t)(1U << i);
}

for (i = 0; i < 4U; i++) {
    double p = wp_output.limited_torque_nm[i] * wheels[i].speed_rad_s;
    if (p >= 0.0) {
        deliv_motoring_w += p;
    } else {
        deliv_regen_w += -p;
    }
    deliv_net_w += p;
    wp_state.previous_torque_nm[i] = wp_output.limited_torque_nm[i];
}

{
    double abs_net = fabs(req_net_w);
    wp_state.filtered_abs_power_w =
        wp_config.filter_alpha * abs_net +
        (1.0 - wp_config.filter_alpha) * wp_state.filtered_abs_power_w;
}

{
    int limit_active = (any_power_limit || any_slew_limit ||
                        wp_state.filtered_abs_power_w >= wp_config.trip_filtered_w) ? 1 : 0;
    if (limit_active) {
        wp_state.mode = WP_LIMITED;
        wp_state.clean = 0U;
    } else if (wp_state.mode == WP_LIMITED || wp_state.mode == WP_RECOVERING) {
        if (wp_state.filtered_abs_power_w <= wp_config.release_filtered_w) {
            if (wp_state.mode == WP_LIMITED) {
                wp_state.mode = WP_RECOVERING;
                wp_state.clean = 1U;
            } else {
                wp_state.clean += 1U;
            }
            if (wp_state.clean >= wp_config.release_cycles) {
                wp_state.mode = WP_NORMAL;
                wp_state.clean = 0U;
            }
        } else {
            wp_state.mode = WP_LIMITED;
            wp_state.clean = 0U;
        }
    } else {
        wp_state.mode = WP_NORMAL;
        wp_state.clean = 0U;
    }
}

for (i = 0; i < 4U; i++) {
    req_torque_body.x += -torque_nm[i] * axis_unit[i][0];
    req_torque_body.y += -torque_nm[i] * axis_unit[i][1];
    req_torque_body.z += -torque_nm[i] * axis_unit[i][2];
    deliv_torque_body.x += -wp_output.limited_torque_nm[i] * axis_unit[i][0];
    deliv_torque_body.y += -wp_output.limited_torque_nm[i] * axis_unit[i][1];
    deliv_torque_body.z += -wp_output.limited_torque_nm[i] * axis_unit[i][2];
}

wp_output.mode = wp_state.mode;
wp_output.clean = wp_state.clean;
wp_output.power_limited_mask = power_mask;
wp_output.slew_limited_mask = slew_mask;
wp_output.requested_net_power_w = req_net_w;
wp_output.delivered_net_power_w = deliv_net_w;
wp_output.requested_motoring_power_w = req_motoring_w;
wp_output.requested_regenerative_power_w = req_regen_w;
wp_output.delivered_motoring_power_w = deliv_motoring_w;
wp_output.delivered_regenerative_power_w = deliv_regen_w;
wp_output.filtered_abs_power_w = wp_state.filtered_abs_power_w;
wp_output.momentum_nms = momentum;
wp_output.momentum_norm_nms = adcs_vec3_norm(&momentum);
wp_output.requested_body_torque_nm = req_torque_body;
wp_output.delivered_body_torque_nm = deliv_torque_body;
